using System.Globalization;
using CraftSurvive.Game.Modules.WorldGen;

namespace CraftSurvive.Game.Modules.Dungeons;

/// <summary>
/// Test aids for the caves under the world (#10924): a cave regenerated now with chosen communities, whatever the cave
/// store, the generator's kept copy, the restored player position or the session's home records hold.
/// </summary>
internal sealed partial class DungeonModule
{
    /// <summary>
    /// Forgets a cave's animals, given its cave key (<c>cave:X,Z</c>): its home records, small creatures and hunters, so a
    /// cave regenerated by <see cref="CaveFresh"/> takes the homes its new layout gives. Wired by the product to wildlife
    /// and the creatures.
    /// </summary>
    internal Action<string>? ForgetCaveAnimals { get; set; }

    private long afreshAsks;

    /// <summary>
    /// Test aid (#10924): stands the player outside the nearest cave mouth with a cave under it, lets that cave go, forgets
    /// its animals and asks for it again now, generated afresh (never read from the store or the generator's kept copy, and
    /// not stored) with the named communities grown, each at least once: a list such as <c>veilforest,glasssteppe</c>;
    /// <c>none</c> grows none of them; <c>auto</c> lets the cave choose by region and depth as it would. The switches hold
    /// for this cave only.
    /// </summary>
    internal string CaveFresh(string communities)
    {
        if (ParseCommunities(communities) is not (KarstCave.Settings settings, string named))
        {
            return $"unknown community in '{communities}': {string.Join(", ", Enum.GetNames<CaveCommunity>().Select(n => n.ToLowerInvariant()))}, none or auto";
        }

        string stood = CaveGoTo(CaveFreshReachMetres);
        if (walkCave is not (long, long) key || !underCaves.TryGetValue(key, out UnderCave? old))
        {
            return stood;
        }

        CavePlacement cave = old.Cave;
        Undress(old);
        if (old.Ready is not null)
        {
            terrain.ReleaseCave(cave);
            cavesReleased++;
        }

        underCaves.Remove(key);
        caveSites.Remove(key);
        ForgetCaveAnimals?.Invoke(CaveKey(cave));
        KarstCave.Settings kept = KarstCave.Next;
        try
        {
            KarstCave.Next = settings;
            Ask(cave, afresh: true);
        }
        finally
        {
            KarstCave.Next = kept;
        }

        walkWay = null;
        walked = 0f;
        return string.Create(CultureInfo.InvariantCulture,
            $"regenerating the cave under the mouth at {cave.Site.X},{cave.Site.Z} afresh with {named}; its animals forgotten; the player stands outside its mouth. Wait for craft.cave.readout ready=1, then craft.wildlife.caves for its homes.");
    }

    /// <summary>How far <see cref="CaveFresh"/> looks for a cave mouth.</summary>
    private const double CaveFreshReachMetres = 3000d;

    /// <summary>The wildlife's name for a cave under the world: its homes and creatures are keyed by it.</summary>
    internal static string CaveKey(CavePlacement cave) => string.Create(CultureInfo.InvariantCulture, $"cave:{cave.Site.CellX},{cave.Site.CellZ}");

    /// <summary>The study settings for a list of communities, and how the list reads; null when a name is unknown.</summary>
    internal static (KarstCave.Settings Settings, string Named)? ParseCommunities(string list)
    {
        KarstCave.Settings settings = KarstCave.Next;
        string[] names = [.. (list ?? "").Split([',', ' ', ';'], StringSplitOptions.RemoveEmptyEntries).Select(Normal)];
        if (names.Length == 0 || names is ["auto"]) return (settings with { NoCommunities = false }, "the communities its region and depth choose");
        if (names is ["none"]) return (settings with { NoCommunities = true }, "no communities");
        settings = settings with { NoCommunities = false };
        foreach (string name in names)
        {
            CaveCommunity[] matched = [.. Enum.GetValues<CaveCommunity>().Where(c => Normal(c.ToString()) == name)];
            if (matched.Length == 0) return null;
            settings = matched[0] switch
            {
                CaveCommunity.VentOrchard => settings with { VentOrchards = Math.Max(1, settings.VentOrchards) },
                CaveCommunity.InvertedGrove => settings with { InvertedGroves = Math.Max(1, settings.InvertedGroves) },
                CaveCommunity.FunnelGarden => settings with { FunnelGardens = Math.Max(1, settings.FunnelGardens) },
                CaveCommunity.GlassSteppe => settings with { GlassSteppes = Math.Max(1, settings.GlassSteppes) },
                CaveCommunity.RibbonThicket => settings with { RibbonThickets = Math.Max(1, settings.RibbonThickets) },
                CaveCommunity.VeilForest => settings with { VeilForests = Math.Max(1, settings.VeilForests) },
                CaveCommunity.CushionBarrens => settings with { CushionBarrens = Math.Max(1, settings.CushionBarrens) },
                _ => settings with { IvoryHeaths = Math.Max(1, settings.IvoryHeaths) },
            };
        }

        return (settings, string.Join(", ", names));

        static string Normal(string name) => name.Replace("-", "", StringComparison.Ordinal).Replace("_", "", StringComparison.Ordinal).ToLowerInvariant();
    }

    /// <summary>The communities the chosen cave grew, once it is ready: <c>craft.cave.goto</c> or <c>craft.cave.fresh</c> chose it.</summary>
    internal string ChosenCaveCommunities() => walkCave is (long, long) key && underCaves.TryGetValue(key, out UnderCave? cave) && cave.Ready is UndergroundCave ready
        ? $"communities=[{string.Join(" ", ready.Layout.Communities)}]"
        : "communities=unknown";
}
